'use strict';
let warehouseExpanded=true,caseSectionExpanded=true;
const caseStatuses=['尚未開始','執行中','結案'];
function caseClass(status){return status==='執行中'?'running':status==='結案'?'closed':'';}
function caseDate(value){return value||'未填寫';}
function moveItem(list,index,direction,label){const target=index+direction;if(index<0||target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];addAudit('調整顯示順序',label,'管理後台');persist();if(location.hash==='#admin')renderAdmin();else render();}
function caseRows(){
 const cases=state.cases||[];
 if(!cases.length)return '<div class="empty">尚未建立案件</div>';
 return cases.map((c,index)=>'<article class="case-item"><div class="case-name"><strong>'+esc(c.name)+'</strong></div><div class="case-value"><span>廠商</span><strong>'+esc(c.vendor||'未填寫')+'</strong></div><div class="case-value"><span>接案日</span><strong>'+esc(caseDate(c.acceptedDate))+'</strong></div><div class="case-value"><span>結案日</span><strong>'+esc(caseDate(c.closedDate))+'</strong></div><div class="case-value"><span>狀態</span><strong class="case-status '+caseClass(c.status)+'">'+esc(c.status)+'</strong></div><div class="order-controls"><button type="button" class="small" data-case-up="'+index+'" '+(index===0?'disabled':'')+'>↑ 上移</button><button type="button" class="small" data-case-down="'+index+'" '+(index===cases.length-1?'disabled':'')+'>↓ 下移</button><button type="button" class="small" data-case-edit="'+esc(c.id)+'">修改</button></div></article>').join('');
}
function workbookDownload(sheets,name){if(!window.XLSX){toast('Excel 元件尚未載入，請重新整理。');return;}const wb=XLSX.utils.book_new();for(const [title,rows] of sheets)XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),title);XLSX.writeFile(wb,name);}
function exportCases(){const rows=[['案件名稱','案件廠商','接案日期','結案日期','狀態'],...(state.cases||[]).map(c=>[c.name,c.vendor||'',c.acceptedDate||'',c.closedDate||'',c.status])];workbookDownload([['案件管理',rows]],'案件管理資料.xlsx');addAudit('匯出案件管理資料',(state.cases||[]).length+' 筆案件','案件管理');persist();}
function exportWarehouse(){const projects=[['專案日期','專案名稱','籃數','庫房位置','零件項數','現有庫存'],...(state.projects||[]).map(p=>[projectDate(p),p.name,p.basketCount??1,p.location||'',p.parts.length,totalStock(p)])],parts=[['專案日期','專案名稱','零件名稱','規格','每套需求','套數','總需求量','已收','現有庫存']];for(const p of state.projects||[])for(const i of p.parts)parts.push([projectDate(p),p.name,i.name,i.spec,i.need,i.sets??1,totalNeed(i),i.received,inStock(p,i.id)]);workbookDownload([['專案總表',projects],['零件與庫存',parts]],'庫房管理資料.xlsx');addAudit('匯出庫房管理資料',(state.projects||[]).length+' 筆專案','庫房管理');persist();}
function enhanceCases(){
 const main=$('main'),demo=$('.demo'),heading=$('.heading'),workspace=$('.workspace'),footer=$('.footer-note');if(!main||!demo||!heading||!workspace||main.querySelector('.case-workspace'))return;
 state.cases??=[];
 const cases=document.createElement('details');cases.className='workspace case-workspace case-fold';cases.open=caseSectionExpanded;cases.innerHTML='<summary><span>'+esc(siteText('casesTitle'))+'</span></summary><div class="case-head"><small>'+esc(siteText('casesDescription'))+'</small><div class="section-actions"><button type="button" id="export-cases">匯出案件資料</button><button type="button" id="new-case" class="primary">＋ 建立專案</button></div></div><div class="case-column-head"><span>案件名稱</span><span>廠商</span><span>接案日</span><span>結案日</span><span>狀態</span><span>順序／管理</span></div><div class="case-list">'+caseRows()+'</div>';demo.after(cases);cases.ontoggle=()=>{caseSectionExpanded=cases.open;};
 const fold=document.createElement('details');fold.className='warehouse-fold';fold.open=warehouseExpanded;fold.innerHTML='<summary>'+esc(siteText('heading'))+'</summary>';heading.before(fold);heading.querySelector('h1')?.remove();const headingActions=document.createElement('div');headingActions.className='section-actions';const exportButton=document.createElement('button');exportButton.type='button';exportButton.id='export-warehouse';exportButton.textContent='匯出庫房資料';headingActions.append(exportButton,$('#new-project'));heading.append(headingActions);fold.append(heading,workspace,footer);fold.ontoggle=()=>{warehouseExpanded=fold.open;};
 $('#new-case').onclick=()=>editCase();$('#export-cases').onclick=exportCases;$('#export-warehouse').onclick=exportWarehouse;
 document.querySelectorAll('[data-case-edit]').forEach(el=>el.onclick=()=>editCase(el.dataset.caseEdit));
 document.querySelectorAll('[data-case-up]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.caseUp),-1,'案件管理順序'));
 document.querySelectorAll('[data-case-down]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.caseDown),1,'案件管理順序'));
 document.querySelectorAll('.project').forEach(article=>{const id=article.querySelector('[data-project]')?.dataset.project,index=state.projects.findIndex(p=>p.id===id),controls=document.createElement('div');controls.className='project-order-controls';controls.innerHTML='<button type="button" class="small" data-project-up="'+index+'" '+(index===0?'disabled':'')+'>↑ 上移</button><button type="button" class="small" data-project-down="'+index+'" '+(index===state.projects.length-1?'disabled':'')+'>↓ 下移</button>';article.append(controls);});
 document.querySelectorAll('[data-project-up]').forEach(el=>el.onclick=()=>moveItem(state.projects,Number(el.dataset.projectUp),-1,'庫房專案順序'));
 document.querySelectorAll('[data-project-down]').forEach(el=>el.onclick=()=>moveItem(state.projects,Number(el.dataset.projectDown),1,'庫房專案順序'));
}
function editCase(id,fromAdmin=false){
 const existing=(state.cases||[]).find(c=>c.id===id),c=existing||{id:crypto.randomUUID(),name:'',vendor:'',acceptedDate:'',closedDate:'',status:'尚未開始'};
 modal(existing?'修改案件資料':'建立專案',field('案件名稱','name',c.name,'required maxlength="100"')+field('案件廠商','vendor',c.vendor,'maxlength="100"')+'<div class="form-grid">'+field('接案日期','acceptedDate',c.acceptedDate,'type="date"')+field('結案日期','closedDate',c.closedDate,'type="date"')+'</div><label class="field">案件狀態<select name="status">'+caseStatuses.map(s=>'<option '+(c.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label>','儲存案件',fd=>{const name=String(fd.get('name')||'').trim();if(!name)error('請填寫案件名稱。');const next={...c,name,vendor:String(fd.get('vendor')||'').trim(),acceptedDate:String(fd.get('acceptedDate')||''),closedDate:String(fd.get('closedDate')||''),status:String(fd.get('status'))};if(next.closedDate&&next.acceptedDate&&next.closedDate<next.acceptedDate)error('結案日期不可早於接案日期。');if(next.status==='結案'&&!next.closedDate)next.closedDate=new Date().toISOString().slice(0,10);if(existing)Object.assign(existing,next);else{state.cases??=[];state.cases.unshift(next);}addAudit(existing?'修改管理案件項目':'新增管理案件項目',next.name,'案件管理 > '+next.name);persist();if(fromAdmin){$('#modal').close();renderAdmin();toast(existing?'案件資料已更新':'案件已建立');}else done(existing?'案件資料已更新':'案件已建立');});
}
const renderBeforeCases=render;render=function(){renderBeforeCases();enhanceCases();};
function enhanceAdminCases(){const main=$('main');if(!main||$('#admin-cases'))return;const cards=main.querySelectorAll('.admin-card'),card=document.createElement('details');card.id='admin-cases';card.className='admin-card';card.innerHTML='<summary><h2>'+esc(siteText('casesTitle'))+'</h2><span>展開／收合</span></summary><div class="admin-card-body"><p>可在後台建立、修改、排序或刪除所有案件資料。</p>'+(state.cases||[]).map((c,i)=>'<div class="admin-row"><strong>'+esc(c.name)+'</strong><span>'+esc(c.vendor||'未填廠商')+' · '+esc(c.status)+'</span><button type="button" data-admin-case-up="'+i+'" '+(i===0?'disabled':'')+'>上移</button><button type="button" data-admin-case-down="'+i+'" '+(i===(state.cases||[]).length-1?'disabled':'')+'>下移</button><button type="button" data-admin-case="'+esc(c.id)+'">修改</button><button type="button" class="danger-button" data-admin-case-delete="'+esc(c.id)+'">刪除</button></div>').join('')+'<div class="admin-actions"><button type="button" id="admin-export-cases">匯出案件資料</button><button type="button" id="admin-new-case">＋ 建立專案</button></div></div>';if(cards[0])cards[0].after(card);else main.append(card);$('#admin-new-case').onclick=()=>editCase(undefined,true);$('#admin-export-cases').onclick=exportCases;document.querySelectorAll('[data-admin-case]').forEach(el=>el.onclick=()=>editCase(el.dataset.adminCase,true));document.querySelectorAll('[data-admin-case-up]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.adminCaseUp),-1,'案件管理順序'));document.querySelectorAll('[data-admin-case-down]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.adminCaseDown),1,'案件管理順序'));document.querySelectorAll('[data-admin-case-delete]').forEach(el=>el.onclick=()=>{const index=state.cases.findIndex(c=>c.id===el.dataset.adminCaseDelete);if(index<0||!confirm('確定刪除案件「'+state.cases[index].name+'」？'))return;const removed=state.cases.splice(index,1)[0];addAudit('刪除管理案件項目',removed.name,'案件管理 > '+removed.name);persist();renderAdmin();toast('案件已刪除');});}
const renderAdminBeforeCases=renderAdmin;renderAdmin=function(){renderAdminBeforeCases();enhanceAdminCases();};
